import os


class Config:
    """
    Central configuration for the Random Forest Baseline pipeline.
    Contains file paths, feature definitions, and model hyperparameters.
    """

    # -------------------------------------------------------------------------
    # File Paths
    # -------------------------------------------------------------------------
    # Input Metadata (Parquet files generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Working Directory for Caching (Intermediate files)
    # Using 'idea_1' as the identifier for this baseline approach
    WORKING_DIR = "./working/idea_1"

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure necessary writeable directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # -------------------------------------------------------------------------
    # Column Definitions
    # -------------------------------------------------------------------------
    ID_COL = "request_id"
    TARGET_COL = "requester_received_pizza"

    # Text features to be concatenated and vectorized
    TEXT_COLS = ["request_title", "request_text"]

    # Numerical features available at the time of request (No Leakage)
    # Excludes all '_at_retrieval' columns
    NUMERICAL_COLS = [
        "requester_account_age_in_days_at_request",
        "requester_days_since_first_post_on_raop_at_request",
        "requester_number_of_comments_at_request",
        "requester_number_of_comments_in_raop_at_request",
        "requester_number_of_posts_at_request",
        "requester_number_of_posts_on_raop_at_request",
        "requester_number_of_subreddits_at_request",
        "requester_upvotes_minus_downvotes_at_request",
        "requester_upvotes_plus_downvotes_at_request",
        "unix_timestamp_of_request",
    ]

    # -------------------------------------------------------------------------
    # Hyperparameters & Settings
    # -------------------------------------------------------------------------
    # Reproducibility
    RANDOM_SEED = 42

    # Development / Debugging
    # Set to a small integer (e.g., 100) to run pipeline on a subset of data.
    # Set to None for full training.
    DEBUG_SAMPLE_SIZE = None

    # Text Vectorization (TF-IDF)
    VECTORIZER_PARAMS = {
        "max_features": 5000,
        "ngram_range": (1, 2),
        "stop_words": "english",
        "binary": False,
        "sublinear_tf": True,  # Apply sublinear scaling (1 + log(tf))
    }

    # Model (Random Forest)
    RF_PARAMS = {
        "n_estimators": 500,
        "max_depth": 20,
        "min_samples_leaf": 2,
        "min_samples_split": 5,
        "class_weight": "balanced",  # Handle class imbalance (approx 1:3)
        "random_state": RANDOM_SEED,
        "n_jobs": -1,  # Use all available vCPUs
        "verbose": 0,
    }
